 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
    by_color = {}
    for r in range(h):
        for c in range(w):
            if g[r][c] != bg:
                by_color.setdefault(g[r][c], []).append((r, c))
    candidates = []
    for color, pts in by_color.items():
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                if r2 != r1 and abs(r2-r1) == abs(c2-c1):
                    dr = 1 if r2 > r1 else -1
                    dc = 1 if c2 > c1 else -1
                    # Continue only when the next cell follows the ray toward the edge.
                    end = (r1, c1) if (r1+dr, c1+dc) == (r2, c2) else (r2, c2)
                    candidates.append((len(pts), end[0], color, dr, dc, end))
    # The target is the sparsest diagonal color; break ties by the one furthest down.
    _, _, color, dr, dc, (r, c) = min(candidates, key=lambda x: (x[0], -x[1]))
    # Orient the ray from the upper point through the lower point.
    pts = by_color[color]
    pairs = [(a, b) for i, a in enumerate(pts) for b in pts[i+1:]
             if b[0] != a[0] and abs(b[0]-a[0]) == abs(b[1]-a[1])]
    a, b = max(pairs, key=lambda p: max(p[0][0], p[1][0]))
    if a[0] > b[0]:
        a, b = b, a
    dr = 1
    dc = 1 if b[1] > a[1] else -1
    r, c = b[0] + dr, b[1] + dc
    while 0 <= r < h and 0 <= c < w:
        g[r][c] = color
        r += dr
        c += dc
    return g
